from pydantic import BaseModel, Field, ValidationError
from typing import Union

class Circle(BaseModel):
    kind: str = Field("circle", const=True)
    radius: float

class Square(BaseModel):
    kind: str = Field("square", const=True)
    side: float

class Drawing(BaseModel):
    shape: Union[Circle, Square]

    @classmethod
    def get_model_for_kind(cls, kind: str):
        if kind == "circle":
            return Circle
        elif kind == "square":
            return Square
        else:
            raise ValidationError("Unknown kind", cls)

    @classmethod
    def parse_obj(cls, obj: dict):
        kind = obj.get("kind")
        model = cls.get_model_for_kind(kind)
        return cls(shape=model.model_validate(obj))

def parse_drawing(data: dict) -> Drawing:
    return Drawing.model_validate(data)

# Example usage:
