    circle_data = {"kind": "circle", "radius": 5.0}
    square_data = {"kind": "square", "side": 4.0}
    unknown_data = {"kind": "unknown", "radius": 3.0}

    try:
        print(parse_drawing(circle_data).model_dump())
        print(parse_drawing(square_data).model_dump())
